import java.util.regex.Pattern;

public class CheckForProperNouns {

    public static boolean containsProperNouns(String sentence) {
        String regexPattern = "\\b[A-Z]{1,}[a-zA-Z]*\\b";
        Pattern pattern = Pattern.compile(regexPattern, Pattern.CASE_INSENSITIVE);
        return pattern.matcher(sentence).find();
    }

    public static void main(String[] args) {
        String exampleSentence = "Jack had a cat named Luna with thirteen lives.";
        boolean containsProperNouns = containsProperNouns(exampleSentence);
        if (containsProperNouns) {
            System.out.println("Proper nouns found!");
        } else {
            System.out.println("No proper nouns found.");
        }
    }

    // Output: "Proper nouns found!" (as Jack, Luna, and thirteen lives are proper nouns)
}﻿#ruby﻿#

