# Funktion "count_vowels", die die Anzahl der Vokale (nur "a", "e", "i", "o", "u") in einem String sagt

def count_vowels(input_string):
    """
    Die Funktion zählt die Anzahl Vokale (nur "a", "e", "i", "o", "u") in einem String.
    """

    # Festlegen von Vokalen
    vowels = ['a', 'e', 'i', 'o', 'u']

    # Initialize the count
    vowel_count = 0

    # Durchlaufen jedes Buchstabens im String
    for char in input_string.lower():
        if char in vowels:
            # Zählt nur Vokale auf
            vowel_count += 1

    # Rückgabe der Anzahl an Vokalen in dem String
    return vowel_count

# Beispiel-Test
