        void ParseFaces(IEnumerable<XElement> faceElements)
        {
            foreach (XElement faceElement in faceElements)
            {
                string color = faceElement.Attribute("color").Value;
                var cubies = new List<Cubi>();
                foreach (XElement cubiElement in faceElement.Elements("cubi"))
