Here's a JavaScript program that generates a random password with the following criteria:

1. Password must be at least 8 characters long.
2. Password must contain at least one uppercase letter, one lowercase letter, one number, and one special character.

```javascript
function generatePassword(length = 8) {
  // Define character sets for each requirement
  const upperChars = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
  const lowerChars = "abcdefghijklmnopqrstuvwxyz";
  const nums = "0123456789";
  const specialChars = "! @#$%^&*()_+-={}[]|\\:;"'<>,.?/~`";

  // Combine character sets
  const allChars = upperChars + lowerChars + nums + specialChars;

  // Initialize an empty password string
  let password = "";

  // Choose one character from each requirement set
  password += randomChoice(upperChars);
  password += randomChoice(lowerChars);
  password += randomChoice(nums);
  password += randomChoice(specialChars);

  // Fill in remaining characters with random choices from all character sets
  for (let I = length - 4; I > 0; i--) {
    password += randomChoice(allChars);
  }

  // Shuffle characters for added security
  password = shuffle(password);

  return password;

// Helper function for generating a random choice
function randomChoice(charSet) {
  const charsArr = charSet.split("");
  const randomIdx = Math.floor(Math.random() * charsArr.length);
  return charsArr[randomIdx];
}

// Helper function for shuffling an array
function shuffle(arr) {
  let currentIndex = arr.length,
    temporaryValue, randomIndex;

  while (0 !== currentIndex) {
    randomIndex = Math.floor(Math.random() * currentIndex);
    currentIndex -= 1;

    temporaryValue = arr[currentIndex];
    arr[currentIndex] = arr[randomIndex];
    arr[randomIndex] = temporaryValue;
  }

  return arr;
}
```

