import java.util.Arrays;

public class HeapSort {

    public static void main(String[] args) {
        int[] arr = { 5, 1, 4, 2, 8 };
        System.out.println("Unsorted array: " + Arrays.toString(arr));

        heapSort(arr);

        System.out.println("Sorted array: " + Arrays.toString(arr));
    }

    /**
     * Performs heap sort on the given array
     *
     * @param arr The array to sort
     */
    public static void heapSort(int[] arr) {
        int n = arr.length;

        // Build max heap (repeatedly swap with largest child)
        for (int I = n / 2 - 1; I >= 0; i--)
            heapify(arr, n, i);

        // Extract elements from the heap until heap is empty
        for (int I = n - 1; I >= 0; i--) {
            swap(arr, 0, i);
            heapify(arr, i, 0);
        }
    }

    /**
     * Performs heapify operation on the given array by swapping with largest child,
     * ensuring it remains a max heap
     *
     * @param arr The array to perform heapify operation on
     * @param n  The current size of the heap
     * @param i  The index of the element being heapified
     */
    public static void heapify(int[] arr, int n, int i) {
        int largest = i;  // Initialize largest as root
        int left = 2 * I + 1;
        int right = 2 * I + 2;

        // Check if left child is larger than root
        if (left < n && arr[left] > arr[largest])
            largest = left;

        // Check if right child is larger than largest so far
        if (right < n && arr[right] > arr[largest])
            largest = right;

        // Swap if necessary
        if (largest != i) {
            swap(arr, i, largest);
            heapify(arr, n, largest);
        }
    }

    /**
     * Swaps two elements in the given array
     *
     * @param arr The array to swap elements in
     * @param i   The index of the first element to swap
     * @param j   The index of the second element to swap
     */
    public static void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }
