  "Carrie wants to travel to New York. She can get a 20% discount on a $850 Delta Airlines flight or a 30% discount on a $1,100 United Airlines flight. How much money will she save if she chooses the cheapest option?",
  "Luke has five times more strawberry jelly beans than vanilla jelly beans. If there are 120 vanilla jelly beans, how many jelly beans are there altogether?",
  "Noemi lost $400 at roulette and $500 at blackjack, but she still had $800 in her wallet. How much did Noemi start with?"
];

// Function to solve mathematical word problems and return the answer
function solveProblem(question) {
  // Split question into parts
  const parts = question.split(". ");

  // Convert math expressions to JavaScript syntax
  function convertSyntax(part) {
    part = part.replace(" ", "");
    part = part.replace("more", "+");
    part = part.replace("total", "t");
    part = part.replace("allowed", "a");
    part = part.replace("she", "x");
    return part;
  }

