   ```typescript
   export const generateJWTToken = (user: any) => {
     const options = {
       expiresIn: '1h',
       algorithm: 'HS256',
     };

     const payload = { userId: user.id };

     const token = jwt.sign(payload, secretKey, options);
     return token;
   };
   ```

   Replace `any` with your own user type, such as an interface or class. This example includes an `expiresIn` option with a value of "1h" and sets the algorithm to HS256. Adjust the options to your needs.

