## Overview

This rule aims to prevent updating component state with side effects within lifecycle hooks, as per the following rule:

**Prohibit updating component state with side effects in lifecycle hooks**

### Examples of violating patterns

1. `created` hook modifying the component's `data` property:

   ```javascript
   export default {
     data() {
       return {
         items: []
       };
     },
     created() {
       fetchItems().then(items => {
         this.items = items; // Violation: modifying the component's data property in lifecycle hook
       });
     },
     // ...
   };
   ```

2. `beforeMount` hook calling a method that changes the component's child nodes:

   ```javascript
   export default {
     data() {
       return {
         todos: []
       };
     },
     beforeMount() {
       todosRef.current.value = this.$children[0].todos.map(todo => ({
         id: todo.id,
         title: todo.title,
         done: todo.done,
       }));
       // Violation: manipulating the component's child nodes in lifecycle hook
     },
     // ...
   };
   ```

## Implementation Details

This rule evaluates expressions in Vue.js lifecycle hooks, and checks whether the expression updates the component's internal state with side effects. The rules for determining if an expression violates the rule are outlined below:

1. The expression is a call to a lifecycle hook method (e.g., `created`, `beforeMount`, etc.).

2. The expression contains an assignment operation (such as `=`) that updates the component's internal state, detected by the following cases:

   a. Updating the component's `data` property:

     ```javascript
     this.data = 'new value'; // Violation

     const dataProp = this.$data;
     dataProp.someProperty = 'new value'; // Violation
     ```

   b. Calling a side-effecting method that modifies the component's internal state object (for example, `$destroy` or updating child nodes):

     ```javascript
     this.$destroy(); // Violation

     const childNode = this.$children[0];
     childNode.todos.push(newTodo); // Violation
     ```

   c. Updating a method's external variable that is scoped within the component.

     ```javascript
     let todosRef = ref([]);
     beforeCreate() {
       todosRef.value = [];
     }

     beforeMount() {
       todosRef.value = this.$children[0].todos.map(todo => ({
         id: todo.id,
         title: todo.title,
         done: todo.done,
       }));
       // Violation: accessing a variable outside current component scope (i.e. `ref`)
     }
     // ...
     ```

The rule includes a fixer that removes the side-effecting statement found.

## Code Explanation

The `prefer-update-without-side-effects` rule consists of a function exported as the `create` method. The `create` method returns an object containing a single rule handler.

```javascript
module.exports = {
  meta: {
    // Rule configuration
  },
  create(context) {
    // Rule handler
  },
};
```

### Rule Handler

The rule handler includes a single expression statement handler (`ExpressionStatement:exit`) that checks for any lifecycle hook calls in the component.

```javascript
create(context) {
  return {
    // ...
    'ExpressionStatement:exit'(node) {
      // Rule implementation
    },
  };
}
```

The `ExpressionStatement:exit` handler takes the AST node of an expression statement as its argument, allowing us to evaluate the expression.

#### Identifying Lifecycle Hook Calls

To identify lifecycle hook calls, we use a simple lookup mechanism based on the property name of the call expression's `callee` node. We look up and check for Vue.js lifecycle hook names in this handler.

```javascript
'ExpressionStatement

Here's a custom ESLint rule for Vue.js that checks if the updated lifecycle hook methods modify the internal component state, and also if they call methods that modify the internal component state:

1. Create a new ECMAScript module file (e.g. `vue-lifecycle-eslint-rule.js`) and add the following dependencies:

   ```javascript
   import Vue from 'vue';
   import type { Rule activating, OnActivate, RuleListener, RuleParams } from 'eslint';
   import { Node } from 'eslint/node/types';

   import { isLifecycleHook } from './utils/lifecycle-hooks';

   // Define rule parameters and default options
   interface RuleOptions {
     allowInternalStateChange?: boolean;
     onlyDetectMethodCalls?: boolean;
   }

   export default function createVueLifecycleHookRule(options: RuleOptions = {}): Rule {

     const { allowInternalStateChange = false, onlyDetectMethodCalls = false } = options;

     function rule(context: RuleListener): Rule activating {
       return {
         NamePath(node: Node, parent: Node) {
           if (isLifecycleHook(node)) {

             // Check if method modifies internal state or calls methods that modify internal state
             const { hasInternalStateChange, hasMethodCallWithInternalStateChange } = checkLifecycleHook(node, parent, allowInternalStateChange, onlyDetectMethodCalls);

             if (hasInternalStateChange) {
               context.report({
                 node,
                 message: 'Lifecycle hook methods should not modify internal component state.',
               });
             }

             if (hasMethodCallWithInternalStateChange) {
               context.report({
                 node,
                 message: 'Lifecycle hook methods should not call methods that modify internal component state.',
               });
             }

           }
         },
       };
     }

     function checkLifecycleHook(node: Node, parent: Node, allowInternalStateChange: boolean, onlyDetectMethodCalls: boolean = false): {
       hasInternalStateChange: boolean,
       hasMethodCallWithInternalStateChange: boolean,
     } {
       let hasInternalStateChange = false;
       let hasMethodCallWithInternalStateChange = false;

       if (allowInternalStateChange === false) {

         // Check if method modifies internal state
         const instancePropertyAccessExpressions = parent?.expressions?.some(Boolean) ? parent.expression.properties : [];
         const componentProps = instancePropertyAccessExpressions.find(property => property.kind === 'Property' && property.key.type === 'Identifier' && property.key.name === 'props')?.value.elements;

         const modifiableStateProperties = componentProps?.filter(prop => prop.type === 'Identifier' && !['$attrs', '$listeners'].includes(prop.name)) || [];

         const stateChangeExpressions = node.modifiers?.some(Boolean) ? node.modifiers.map(modifier => modifier.range[1]) : [node.range[1]];

         hasInternalStateChange = stateChangeExpressions.some(index => modifiableStateProperties.some(prop => Vue.prototype.$refs[Vue.componentName].$data[prop.name] === parent?.expressions?.[0].range[1] + index));

         if (!onlyDetectMethodCalls) {
           // Check if method calls methods that modify internal state
           const methodCalls = node.body.body.filter(statement => statement.type === 'CallExpression').map(call => call?.callee?.object);
           hasMethodCallWithInternalStateChange = methodCalls.some(method => {
             if (method.type === 'MemberExpression') {
               return method.object.type === 'ThisExpression' && Vue.prototype.$refs[Vue.componentName].$data.hasOwnProperty(method.property.name);
             }
             return false;
           });
         }

       }

       return { hasInternalStateChange, hasMethodCallWithInternalStateChange };
     }

     function onActivate(options: RuleParams['options']): void {
       // Load and cache your external dependencies, such as vue-eslint-parser or vscode-eslint-parser
       Vue.use({ directives: [] });
     }

     return {
       create: (context:RuleContext) => rule(context),
       meta: {
         type: 'problem',
         fixable: 'code',
         docs: {
           description: 'Require lifecycle hook methods to not modify internal component state and prevent calling methods that modify internal state.',
           deprecated: false,
         },
         fixableTypes: ['Whitespace'],
         schema: [
           {
             type: 'object',
             properties: {
               allowInternalStateChange: {
                 type: 'boolean',
                 default: false,
               },
               onlyDetectMethodCalls: {
                 type: 'boolean',
                 default: false,
               },
             },
             additionalProperties: false,
           },
         ],
       },
       onActivate,
     } as Rule;
   }

   // Import custom helper functions
   // ...

   // Add further helper functions as needed
   // ...
```

